import path from "node:path";
import fs from "node:fs";

export async function initCommand() {
  const cwd = process.cwd();
  const configPath = path.join(cwd, "ota.config.js");

  if (fs.existsSync(configPath)) {
    console.log("ota.config.js already exists.");
    return;
  }

  let appId = "my-app";
  const pkgPath = path.join(cwd, "package.json");
  if (fs.existsSync(pkgPath)) {
    const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf-8")) as { name?: string };
    if (pkg.name) appId = pkg.name;
  }

  const config = `// Sphegatti OTA configuration
// Generated by: npx ota init
module.exports = {
  appId: '${appId}',
  runtimeVersion: '1',

  publish: {
    serverUrl: 'https://sphegatti.onrender.com',
    // Store your API key in an env var — never commit it directly.
    apiKey: process.env.SPHEGATTI_API_KEY || '',
  },
};
`;

  fs.writeFileSync(configPath, config);

  console.log("✓ Created ota.config.js");
  console.log("");
  console.log("─── Android native integration ─────────────────────────────────");
  console.log("");
  console.log("1. Add OtaModule.kt to android/app/src/main/java/<pkg>/");
  console.log("2. Add OtaPackage.kt to android/app/src/main/java/<pkg>/");
  console.log("3. Register in MainApplication.kt:");
  console.log("");
  console.log("   PackageList(this).packages.apply {");
  console.log("     add(OtaPackage())");
  console.log("   }");
  console.log("");
  console.log("─── JS usage ───────────────────────────────────────────────────");
  console.log("");
  console.log("   import { NativeModules } from 'react-native';");
  console.log("   const { OtaModule } = NativeModules;");
  console.log("   await OtaModule.downloadAndActivate(bundleUrl);");
  console.log("");
  console.log("─── Next steps ─────────────────────────────────────────────────");
  console.log("");
  console.log("   export SPHEGATTI_API_KEY=<your-key>");
  console.log("   npx ota publish --platform android --channel production");
  console.log("");
}
